import { DOCUMENT } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  HostListener,
  Inject,
  OnInit,
  ViewChild
} from '@angular/core';
import { Observable } from 'rxjs';
import { finalize, take, takeUntil } from 'rxjs/operators';
import { DestroySubject, DialogService } from '@honoregaming/core';
import {
  AuthService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  MenuShortcut,
  SmarticoService,
  TelemetryService
} from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { IconDesignType } from '@honoregaming/types';
import { MobileNavService } from 'projects/customer/customer/src/app/services/mobile-nav.service';
import { CharityService } from 'projects/customer/hg-about/src/lib/services/charity.service';
import { DpType } from 'projects/customer/hg-core/src/lib/models/smartico-sdk.model';

@Component({
  selector: 'hg-shortcuts',
  templateUrl: './shortcuts.component.html',
  styleUrls: ['./shortcuts.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ShortcutsComponent extends DestroySubject implements OnInit, AfterViewInit {
  searchButtonOrder?: string;
  allSportsButtonOrder?: string;
  missionsButtonOrder?: string;
  charityButtonOrder?: string;
  displaySearchPopin: boolean = false;
  hideAllSportsButton: boolean = false;
  hideCharityButton: boolean = true;
  readonly showSmarticoMissions: boolean = this.smarticoService.showMissions;

  shortcutsLinks: any[];
  isLoading = false;
  iconDesign: IconDesignType;
  IconDesignType = IconDesignType;
  operatorKey: string | undefined;

  missionsCount$?: Observable<number>;

  @HostListener('window:resize', ['$event'])
  onResize(event) {
    if (event && this.slideElement) {
      if (this.slideElement.nativeElement.scrollWidth <= window.screen.width) {
        this.slideArrowRight.nativeElement.style.display = 'none';
        this.slideArrowLeft.nativeElement.style.display = 'none';
      } else {
        this.slideArrowRight.nativeElement.style.display = 'flex';
      }
    }
  }

  @HostListener('scroll', ['$event'])
  public scrollHandler(event: any) {
    const position = Math.round(event.currentTarget.scrollLeft + event.currentTarget.offsetWidth);
    const width = event.currentTarget.scrollWidth;

    if (position === width) {
      this.slideArrowRight.nativeElement.style.display = 'none';
    } else if (event.currentTarget.scrollLeft === 0) {
      this.slideArrowLeft.nativeElement.style.display = 'none';
    } else {
      this.slideArrowLeft.nativeElement.style.display = 'flex';
      this.slideArrowRight.nativeElement.style.display = 'flex';
    }
  }

  @ViewChild('slideArrowLeft', { static: false }) slideArrowLeft!: ElementRef;
  @ViewChild('slideArrowRight', { static: false }) slideArrowRight!: ElementRef;
  @ViewChild('slideElement', { static: false }) slideElement!: ElementRef;

  constructor(
    @Inject(DOCUMENT) private document: any,
    private cdRef: ChangeDetectorRef,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration,
    private mobileNavService: MobileNavService,
    private readonly charityService: CharityService,
    private telemetryService: TelemetryService,
    private i18nService: I18nService,
    private readonly authService: AuthService,
    private readonly smarticoService: SmarticoService,
    private readonly dialogService: DialogService
  ) {
    super();
  }
  ngOnInit(): void {
    this.getMobileShortCuts();
    this.iconDesign =
      this.customerOperatorConfiguration.themeCustomizationConfiguration?.iconDesign ?? IconDesignType.Default;
    this.setupMissionsCount();
  }

  ngAfterViewInit() {
    if (this.slideElement?.nativeElement.scrollWidth <= window.screen.width) {
      this.slideArrowRight.nativeElement.style.display = 'none';
      this.slideArrowLeft.nativeElement.style.display = 'none';
    }
  }

  getMobileShortCuts() {
    const homePageCustomization =
      this.customerOperatorConfiguration.customization['homepage'] ??
      this.customerOperatorConfiguration.customization['sports-homepage'];

    if (homePageCustomization['shortcutsLinks']) {
      this.isLoading = true;
      this.searchButtonOrder = homePageCustomization.searchButtonOrder;
      this.allSportsButtonOrder = homePageCustomization.allSportsButtonOrder;
      this.missionsButtonOrder = homePageCustomization.missionsButtonOrder ?? '98';
      this.charityButtonOrder = homePageCustomization.charityButtonOrder ?? '99';
      this.hideAllSportsButton = homePageCustomization.hideAllSportsButton;

      if (homePageCustomization.useThreeDimensionIconsPerOperator ?? false) {
        this.operatorKey = this.customerOperatorConfiguration.key;
      }

      this.shortcutsLinks = homePageCustomization['shortcutsLinks'].map(x => {
        this.isLoading = false;
        this.cdRef.markForCheck();
        return x;
      });

      if (this.customerOperatorConfiguration.operatorFeatures?.indexOf('Charity') > -1) {
        this.charityService
          .showCharityNavigation()
          .pipe(
            takeUntil(this.destroy$),
            finalize(() => {
              this.cdRef.markForCheck();
            })
          )
          .subscribe(showCharityNavigation => {
            this.hideCharityButton = !showCharityNavigation;
          });
      }
    }
  }

  public onNextPosition() {
    this.slideElement.nativeElement.scrollLeft += 180;
    this.slideArrowLeft.nativeElement.style.display = 'flex';
  }

  public onPreviousPosition() {
    this.slideElement.nativeElement.scrollLeft -= 180;
    this.slideArrowRight.nativeElement.style.display = 'flex';
  }

  toggleSearchPopin() {
    this.telemetryService.trackEvent('homepage_shortcut_click', {
      shortcut_name: 'search',
      shortcut_position: this.searchButtonOrder
    });
    this.displaySearchPopin = !this.displaySearchPopin;
    this.document.documentElement.classList.toggle('hidden');
  }

  openMenu() {
    this.telemetryService.trackEvent('homepage_shortcut_click', {
      shortcut_name: 'all_sports',
      shortcut_position: this.allSportsButtonOrder
    });
    this.mobileNavService.clickOnBurgerMenu(true, 'jumpSportsSectionMenu');
  }

  openDrawer(drawerType: string) {
    this.mobileNavService.clickOnBurgerMenu(true, drawerType);
  }

  charityButtonClick() {
    this.telemetryService.trackEvent('homepage_shortcut_click', {
      shortcut_name: 'charity',
      shortcut_position: this.charityButtonOrder,
      shortcut_destination: '/about/charities'
    });
  }

  shortCutClick(shortCut: MenuShortcut, index: number) {
    var name = this.i18nService.translateSync('NAV.' + shortCut.text.toUpperCase());
    if (name.includes('NOT FOUND')) {
      name = shortCut.text;
    }

    this.telemetryService.trackEvent('homepage_shortcut_click', {
      shortcut_name: name,
      shortcut_position: index,
      shortcut_destination: shortCut.action.url
    });
  }

  missionsButtonClick(): void {
    this.authService.status$.pipe(take(1)).subscribe(status => {
      if (status === 'connected') {
        this.smarticoService.executeDeepLink(DpType.Missions);
      } else {
        this.dialogService.toggleDialog('login', true);
      }
    });
  }

  private setupMissionsCount(): void {
    if (!this.smarticoService.isEnabled) {
      return;
    }
    this.missionsCount$ = this.smarticoService.missionsCount$;
  }
}
